/*
 * THE DOCS' PLACEHOLDER PICTURES: satin folds with film grain, generated by `tools/frost-backdrop` and served from
 * `public/demos/satin/` (and, under the old photo names, `public/demos/lightbox/`). Wherever an example needs "an image"
 * and nothing in particular is in it (a card's media, a hero's screenshot slot, a thumbnail), it is one of these: local,
 * so nothing fetches a stranger's photo and every demo works offline, and the same look as the backdrop behind a frosted
 * example.
 *
 *  - DARK tints (`graphite blue sand sage lilac slate`): `16x9`, `4x3` and `thumb` (320x240, for a small preview).
 *  - PALE tints (`pearl mist blush`): `16x9`, `4x5` and, for pearl, `1x1`. For an example that needs a bright picture, such as a
 *    wash that holds white text: over a dark one the wash would show nothing.
 */
export const SATIN_TINTS = ["graphite", "blue", "sand", "sage", "lilac", "slate"] as const;
export const SATIN_PALE_TINTS = ["pearl", "mist", "blush"] as const;
export type SatinTint = (typeof SATIN_TINTS)[number];
export type SatinPaleTint = (typeof SATIN_PALE_TINTS)[number];

export function satin(tint: SatinTint, shape?: "16x9" | "4x3" | "thumb"): string;
export function satin(tint: SatinPaleTint, shape?: "16x9" | "4x5" | "1x1"): string;
export function satin(tint: SatinTint | SatinPaleTint, shape = "16x9"): string {
  return `/demos/satin/satin-${tint}-${shape}.jpg`;
}
